const runs = (i: number) => join(wt(i), `.agents/specs/${SL[i]}/runs/_story`);
const sliceWt = () => `${wt(4)}--01-part`;
const sliceRuns = () => join(sliceWt(), `.agents/specs/${SL[4]}/runs/01-part`);
const tick = async () => { h.clock.advance(10_000); return h.tick(); };
